input.content:
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Share+Tech+Mono&display=swap');

:root {
  --ink: #e7e2d2;
  --muted: #9b9a8f;
  --dim: #666b67;
  --nato: #78a7c8;
  --nato-deep: #163143;
  --wp: #d45448;
  --wp-deep: #43191a;
  --amber: #e8b663;
  --panel: rgba(9, 12, 14, 0.82);
  --line: rgba(231, 226, 210, 0.18);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body, #app { width: 100%; height: 100%; margin: 0; overflow: hidden; background: #050607; }
body {
  color: var(--ink);
  font-family: 'Barlow Condensed', 'Arial Narrow', Arial, sans-serif;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}
button { font: inherit; color: inherit; }
canvas#game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; image-rendering: pixelated; }
.hidden { display: none !important; }

.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  background: radial-gradient(circle at 50% 44%, rgba(21, 30, 35, 0.18), rgba(3, 5, 6, 0.86) 74%), linear-gradient(180deg, rgba(4, 6, 8, 0.4), rgba(3, 4, 5, 0.76));
  overflow: hidden;
}
.screen::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, transparent 0 2px, rgba(0, 0, 0, 0.12) 2px 3px);
  mix-blend-mode: multiply;
  opacity: 0.55;
}

/* boot */
#boot { display: grid; place-items: center; background: #050708; z-index: 60; }
.boot-inner { width: min(620px, 86vw); text-align: center; animation: bootIn 0.8s ease both; }
.boot-kicker { color: var(--amber); font-family: 'Share Tech Mono', monospace; letter-spacing: 0.25em; font-size: 11px; margin-bottom: 14px; }
.boot-title { margin: 0; font-size: clamp(58px, 10vw, 118px); line-height: 0.78; letter-spacing: -0.04em; font-weight: 900; }
.boot-title span { display: block; color: transparent; -webkit-text-stroke: 1px rgba(231, 226, 210, 0.4); font-size: 0.53em; letter-spacing: 0.23em; margin-top: 12px; }
.boot-rule { height: 1px; background: linear-gradient(90deg, transparent, var(--line), transparent); margin: 30px 0 20px; }
.boot-copy { font-family: 'Share Tech Mono', monospace; font-size: 11px; letter-spacing: 0.22em; color: var(--muted); }
.boot-bar { width: min(320px, 70%); height: 3px; margin: 18px auto 0; background: rgba(255,255,255,0.08); overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 42%; background: var(--amber); animation: bootLoad 1.6s cubic-bezier(.2,.7,.2,1) infinite; }
@keyframes bootLoad { 0% { transform: translateX(-110%); } 100% { transform: translateX(280%); } }
@keyframes bootIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }

/* menu */
#menu { display: flex; flex-direction: column; padding: calc(26px + var(--safe-t)) clamp(20px, 5vw, 72px) calc(20px + var(--safe-b)); background: linear-gradient(90deg, rgba(4,6,8,0.9) 0%, rgba(4,6,8,0.16) 34%, rgba(4,6,8,0.1) 66%, rgba(4,6,8,0.82) 100%), linear-gradient(180deg, rgba(4,6,8,0.48), transparent 30%, transparent 70%, rgba(3,4,5,0.9)); }
#menu::before { content: ''; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(90deg, transparent 49.85%, rgba(231,226,210,0.16) 50%, transparent 50.15%); opacity: 0.5; }
.menu-top { display: flex; justify-content: space-between; align-items: flex-start; position: relative; z-index: 2; }
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { display: grid; place-items: center; width: 42px; height: 42px; border: 1px solid rgba(231,226,210,0.5); font-family: 'Share Tech Mono', monospace; font-size: 14px; letter-spacing: 0.05em; background: rgba(6,9,10,0.56); }
.brand strong { display: block; letter-spacing: 0.16em; font-size: 16px; font-weight: 800; }
.brand small { display: block; color: var(--muted); font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.17em; margin-top: 3px; }
.menu-status { font-family: 'Share Tech Mono', monospace; font-size: 9px; letter-spacing: 0.12em; color: var(--muted); text-align: right; }
.menu-status i { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: #87b27a; box-shadow: 0 0 12px #87b27a; margin-right: 5px; animation: pulse 2s infinite; }
.menu-status b { display: block; color: var(--ink); font-size: 19px; font-weight: 400; margin-top: 4px; letter-spacing: 0.1em; }
@keyframes pulse { 50% { opacity: 0.35; } }

.menu-title { position: relative; z-index: 2; margin-top: clamp(28px, 6vh, 72px); max-width: 720px; }
.eyebrow { font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 0.19em; color: var(--amber); margin: 0 0 12px; }
.menu-title h2 { margin: 0; font-size: clamp(48px, 8.1vw, 114px); line-height: 0.8; font-weight: 900; letter-spacing: -0.045em; text-shadow: 0 8px 40px rgba(0,0,0,0.35); }
.menu-title h2 em { color: transparent; -webkit-text-stroke: 1px rgba(231,226,210,0.56); font-style: normal; }
.menu-title p { max-width: 470px; margin: 24px 0 0; color: #bbb9ad; font-size: 17px; line-height: 1.3; letter-spacing: 0.02em; font-weight: 500; }

.faction-picker { position: relative; z-index: 3; display: grid; grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr); align-items: stretch; gap: 0; width: min(880px, 100%); margin: auto auto 0; }
.faction-card { position: relative; text-align: left; border: 1px solid var(--line); background: linear-gradient(155deg, rgba(17, 24, 26, 0.86), rgba(6, 8, 9, 0.88)); padding: 20px 22px 18px; min-height: 260px; cursor: pointer; overflow: hidden; transition: transform .22s ease, border-color .22s ease, background .22s ease; backdrop-filter: blur(6px); }
.faction-card:hover, .faction-card:focus-visible { transform: translateY(-5px); outline: none; }
.faction-card.nato:hover, .faction-card.nato:focus-visible { border-color: rgba(120, 167, 200, 0.72); background: linear-gradient(155deg, rgba(22, 49, 67, 0.82), rgba(6, 8, 9, 0.92)); }
.faction-card.wp:hover, .faction-card.wp:focus-visible { border-color: rgba(212, 84, 72, 0.72); background: linear-gradient(155deg, rgba(67, 25, 26, 0.82), rgba(6, 8, 9, 0.92)); }
.faction-card::after { content: ''; position: absolute; width: 220px; height: 220px; border: 1px solid rgba(255,255,255,0.08); border-radius: 50%; right: -90px; bottom: -110px; }
.card-scan { position: absolute; inset: 0; pointer-events: none; background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(255,255,255,0.018) 3px 4px); }
.card-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.alliance-emblem { width: 28px; height: 28px; display: grid; place-items: center; font-size: 14px; border: 1px solid currentColor; }
.nato-emblem { color: var(--nato); }
.wp-emblem { color: var(--wp); }
.card-tag { font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.2em; color: var(--muted); }
.faction-card h3 { margin: 0; font-size: 43px; line-height: 0.85; font-weight: 900; letter-spacing: -0.02em; }
.faction-card.wp h3 { font-size: 36px; }
.faction-card .unit { margin: 8px 0 16px; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.14em; color: var(--muted); }
.loadout { display: flex; flex-direction: column; gap: 4px; color: #c7c4b8; font-size: 13px; letter-spacing: 0.03em; border-top: 1px solid var(--line); padding-top: 11px; }
.loadout b { color: var(--ink); font-weight: 700; }
.card-stats { margin-top: 15px; display: flex; flex-direction: column; gap: 5px; }
.card-stats span { display: grid; grid-template-columns: 82px 1fr; align-items: center; font-family: 'Share Tech Mono', monospace; color: var(--muted); font-size: 8px; letter-spacing: 0.1em; }
.card-stats i { display: block; height: 2px; background: rgba(255,255,255,0.1); position: relative; }
.card-stats i::after { content: ''; position: absolute; inset: 0; width: var(--v); background: currentColor; opacity: 0.8; }
.nato .card-stats { color: var(--nato); }
.wp .card-stats { color: var(--wp); }
.deploy { display: flex; justify-content: space-between; align-items: center; margin-top: 16px; padding-top: 12px; border-top: 1px solid var(--line); font-family: 'Share Tech Mono', monospace; font-size: 9px; letter-spacing: 0.13em; }
.deploy b { font-size: 20px; transition: transform .2s ease; }
.faction-card:hover .deploy b { transform: translateX(5px); }
.versus { display: grid; place-items: center; align-content: center; gap: 7px; color: var(--muted); }
.versus > span { font-family: 'Share Tech Mono', monospace; font-size: 12px; color: var(--amber); }
.versus small { font-family: 'Share Tech Mono', monospace; font-size: 6px; letter-spacing: 0.15em; line-height: 1.7; text-align: center; }
.menu-foot { position: relative; z-index: 3; display: flex; justify-content: space-between; gap: 18px; align-items: flex-end; padding-top: 18px; }
.controls-line { font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.09em; color: #85867f; display: flex; gap: 14px; flex-wrap: wrap; align-items: center; }
.controls-line span { color: var(--ink); border: 1px solid rgba(255,255,255,0.22); padding: 2px 5px; }
.build-line { font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.11em; color: #716f67; }
.build-line b { color: var(--amber); }

/* briefing */
#briefing { display: grid; place-items: center; background: rgba(3, 5, 6, 0.7); backdrop-filter: blur(4px); }
.briefing-card { position: relative; width: min(560px, 90vw); padding: 34px 38px 30px; background: #101513; border: 1px solid rgba(231,226,210,0.34); box-shadow: 0 30px 90px rgba(0,0,0,0.55); animation: cardIn .3s ease both; }
.briefing-card::before { content: ''; position: absolute; inset: 8px; border: 1px solid rgba(231,226,210,0.08); pointer-events: none; }
.briefing-side { position: absolute; top: 0; right: 0; background: var(--nato); color: #071015; font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 0.16em; padding: 6px 13px; }
.briefing-card.wp .briefing-side { background: var(--wp); color: #180807; }
.briefing-card.wp .briefing-stamp { color: var(--wp); border-color: var(--wp); }
.briefing-stamp { position: absolute; right: 36px; bottom: 84px; color: #c8a05c; border: 2px solid #c8a05c; padding: 3px 8px; font-family: 'Share Tech Mono', monospace; font-size: 9px; letter-spacing: 0.17em; transform: rotate(-7deg); opacity: 0.62; }
.briefing-card h2 { font-size: clamp(38px, 6vw, 56px); line-height: 0.92; margin: 8px 0 14px; letter-spacing: -0.02em; font-weight: 900; }
.briefing-card > p:not(.eyebrow) { color: #bbbaad; font-size: 17px; line-height: 1.32; max-width: 420px; }
.briefing-meta { display: flex; gap: 26px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 12px 0; margin: 20px 0; }
.briefing-meta div { display: flex; flex-direction: column; gap: 3px; }
.briefing-meta small { font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.15em; color: var(--muted); }
.briefing-meta b { font-family: 'Share Tech Mono', monospace; font-size: 11px; font-weight: 400; letter-spacing: 0.08em; }
.primary-btn { width: 100%; border: 1px solid var(--amber); background: var(--amber); color: #171107; padding: 13px 16px; cursor: pointer; font-weight: 800; letter-spacing: 0.14em; font-size: 13px; display: flex; justify-content: space-between; align-items: center; transition: background .18s, color .18s; }
.primary-btn:hover { background: #f5ca7e; }
.primary-btn b { font-size: 20px; }
.brief-hint { display: block; text-align: center; margin-top: 11px; font-family: 'Share Tech Mono', monospace; color: var(--muted); font-size: 8px; letter-spacing: 0.08em; }

/* hud */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; font-family: 'Barlow Condensed', sans-serif; }
#hud::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 48%, rgba(0,0,0,0.28) 100%); }
.hud-top { position: absolute; top: calc(18px + var(--safe-t)); left: 24px; right: 24px; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
.hud-unit { display: flex; align-items: center; gap: 9px; opacity: .92; }
.hud-badge { display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid currentColor; color: var(--nato); font-size: 14px; }
.hud-unit b { display: block; font-size: 15px; letter-spacing: 0.15em; line-height: 1; }
.hud-unit small { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.12em; color: var(--muted); margin-top: 4px; }
.objective { text-align: center; padding-top: 1px; text-shadow: 0 2px 8px rgba(0,0,0,0.8); }
.objective small { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.22em; color: var(--amber); margin-bottom: 4px; }
.objective b { display: block; font-size: 18px; letter-spacing: 0.11em; font-weight: 700; }
.objective span { display: inline-block; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.12em; color: #a6a69c; margin-top: 3px; }
.objective span i { color: var(--ink); font-style: normal; }
.hud-time { text-align: right; }
.hud-time small { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.17em; color: var(--muted); }
.hud-time b { font-family: 'Share Tech Mono', monospace; font-weight: 400; font-size: 18px; letter-spacing: 0.08em; }
.hud-time span { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.11em; color: #bc9d68; margin-top: 2px; }
.hud-time i { display: inline-block; width: 4px; height: 4px; border-radius: 50%; background: var(--wp); margin-right: 4px; animation: pulse 1.6s infinite; }
.hud-left { position: absolute; left: 24px; bottom: calc(24px + var(--safe-b)); display: flex; align-items: flex-end; gap: 18px; }
.vitals { width: 210px; }
.vital-label { display: flex; align-items: baseline; justify-content: space-between; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.13em; color: #b0b0a6; margin-bottom: 4px; }
.vital-label b { font-size: 12px; font-weight: 400; color: var(--ink); }
.vital-track { height: 5px; background: rgba(0,0,0,0.48); border: 1px solid rgba(255,255,255,0.16); margin-bottom: 8px; }
.vital-track i { display: block; height: 100%; background: #c7b66b; transition: width .18s ease; }
.armor-label { color: #979e9f; }
.armor-track { height: 3px; }
.armor-track i { background: #7d9ba3; }
.wave-box { display: flex; align-items: baseline; gap: 4px; padding-bottom: 1px; font-family: 'Share Tech Mono', monospace; color: var(--muted); }
.wave-box span { font-size: 7px; letter-spacing: 0.11em; margin-right: 2px; }
.wave-box b { font-size: 28px; font-weight: 400; color: var(--ink); line-height: 1; }
.wave-box small { font-size: 10px; }
.hud-right { position: absolute; right: 24px; bottom: calc(24px + var(--safe-b)); text-align: right; }
.weapon-name small { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.15em; color: var(--muted); }
.weapon-name b { display: block; font-size: 17px; letter-spacing: 0.12em; line-height: 1.05; }
.weapon-name span { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.1em; color: var(--amber); margin-top: 2px; }
.ammo { display: flex; justify-content: flex-end; align-items: baseline; gap: 5px; margin-top: 6px; text-shadow: 0 2px 10px #000; }
.ammo b { font-family: 'Share Tech Mono', monospace; font-size: 43px; line-height: 0.9; font-weight: 400; }
.ammo span { font-family: 'Share Tech Mono', monospace; color: var(--muted); font-size: 15px; }
.ammo i { font-family: 'Share Tech Mono', monospace; font-style: normal; font-size: 17px; color: #9d9c92; }
.ammo-type { display: flex; justify-content: flex-end; gap: 9px; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.09em; color: var(--muted); margin-top: 4px; }
.ammo-type i { font-style: normal; color: var(--amber); }
.grenades { display: flex; justify-content: flex-end; align-items: center; gap: 8px; margin-top: 10px; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.08em; color: var(--muted); }
.grenades b { color: var(--ink); font-size: 15px; font-weight: 400; }
.crosshair { position: absolute; top: 50%; left: 50%; width: 28px; height: 28px; transform: translate(-50%, -50%); opacity: .85; }
.crosshair i { position: absolute; background: rgba(239, 234, 218, 0.86); box-shadow: 0 0 2px rgba(0,0,0,0.9); }
.ch-t, .ch-b { width: 1px; height: 7px; left: 13px; }
.ch-l, .ch-r { height: 1px; width: 7px; top: 13px; }
.ch-t { top: 0; } .ch-b { bottom: 0; } .ch-l { left: 0; } .ch-r { right: 0; }
.hitmark { position: absolute; top: 50%; left: 50%; width: 20px; height: 20px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; }
.hitmark::before, .hitmark::after { content: ''; position: absolute; background: #f3d6a0; width: 1px; height: 20px; left: 9px; top: 0; }
.hitmark::after { transform: rotate(90deg); }
.hitmark.on { opacity: 1; animation: hit .16s ease; }
@keyframes hit { 0% { transform: translate(-50%,-50%) rotate(45deg) scale(1.4); } 100% { transform: translate(-50%,-50%) rotate(45deg) scale(1); } }
.damage-flash { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at center, transparent 38%, rgba(146, 20, 16, 0.58) 100%); opacity: 0; transition: opacity .1s; }
.damage-flash.on { opacity: 1; }
.feed { position: absolute; top: 100px; right: 24px; display: flex; flex-direction: column; align-items: flex-end; gap: 3px; font-family: 'Share Tech Mono', monospace; font-size: 9px; color: #ddd9ca; text-shadow: 0 1px 3px #000; }
.feed span { background: rgba(5,8,9,0.5); padding: 3px 6px; animation: feedIn .25s ease; }
.feed span b { color: var(--amber); font-weight: 400; }
@keyframes feedIn { from { opacity: 0; transform: translateX(8px); } }
.wave-banner { position: absolute; top: 32%; left: 50%; transform: translate(-50%, -50%); text-align: center; opacity: 0; pointer-events: none; }
.wave-banner.show { animation: waveBanner 2.8s ease both; }
.wave-banner small { display: block; font-family: 'Share Tech Mono', monospace; color: var(--amber); font-size: 9px; letter-spacing: 0.3em; }
.wave-banner b { display: block; font-size: 74px; line-height: 0.95; font-weight: 900; letter-spacing: -0.02em; }
.wave-banner span { display: block; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.18em; color: #b9b6a9; margin-top: 5px; }
@keyframes waveBanner { 0% { opacity: 0; transform: translate(-50%, -40%) scale(1.04); } 14%, 72% { opacity: 1; transform: translate(-50%, -50%) scale(1); } 100% { opacity: 0; transform: translate(-50%, -58%) scale(0.98); } }
.center-toast { position: absolute; left: 50%; bottom: 24%; transform: translateX(-50%); font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 0.15em; color: var(--amber); opacity: 0; transition: opacity .2s; text-shadow: 0 2px 8px #000; white-space: nowrap; }
.center-toast.on { opacity: 1; }

/* result + pause */
#pause, #result { display: grid; place-items: center; background: rgba(3, 5, 6, 0.74); backdrop-filter: blur(5px); }
.pause-card, .result-card { position: relative; width: min(520px, 90vw); background: #101513; border: 1px solid rgba(231,226,210,0.3); padding: 34px 38px; box-shadow: 0 30px 90px rgba(0,0,0,0.55); animation: cardIn .25s ease both; }
@keyframes cardIn { from { opacity: 0; transform: translateY(10px); } }
.pause-card h2, .result-card h2 { margin: 4px 0 8px; font-size: 68px; line-height: 0.85; font-weight: 900; letter-spacing: -0.03em; }
.pause-card > p:not(.eyebrow), .result-card > p:not(.eyebrow) { color: #b3b1a5; font-size: 16px; margin: 0 0 22px; }
.pause-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 20px; margin: 20px 0 25px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 14px 0; }
