.pause-controls span { color: var(--ink); }
.ghost-btn { width: 100%; margin-top: 10px; border: 1px solid rgba(231,226,210,0.2); background: transparent; padding: 11px; color: #9d9c92; font-family: 'Share Tech Mono', monospace; font-size: 8px; letter-spacing: 0.14em; cursor: pointer; transition: border-color .18s, color .18s; }
