503: function movePlayer(dt) {
504:   const forward = (keys.KeyW || keys.ArrowUp ? 1 : 0) - (keys.KeyS || keys.ArrowDown ? 1 : 0) - touch.moveY;
505:   const strafe = (keys.KeyD || keys.ArrowRight ? 1 : 0) - (keys.KeyA || keys.ArrowLeft ? 1 : 0) + touch.moveX;
506:   const input = new THREE.Vector2(strafe, forward);
507:   if (input.lengthSq() > 1) input.normalize();
508:   const speed = player.crouch ? 2.45 : 5.2;
509:   const sin = Math.sin(yaw), cos = Math.cos(yaw);
510:   const dx = (input.x * cos - input.y * sin) * speed * dt;
511:   const dz = (-input.x * sin - input.y * cos) * speed * dt;
512:   const nx = THREE.MathUtils.clamp(player.x + dx, -11.9, 11.9);
513:   if (!collidesAt(nx, player.z)) player.x = nx;
514:   const nz = THREE.MathUtils.clamp(player.z + dz, -71, 13.8);
515:   if (!collidesAt(player.x, nz)) player.z = nz;
516:   isMoving = input.lengthSq() > 0.025;
517:   if (isMoving) bobTime += dt * (player.crouch ? 7 : 10);
518:   const bob = isMoving ? Math.sin(bobTime) * (player.crouch ? 0.018 : 0.035) : 0;
519:   player.y = THREE.MathUtils.damp(player.y, player.crouch ? 1.12 : 1.68, 12, dt);
520:   camera.position.set(player.x, player.y + bob, player.z);
521:   camera.rotation.set(pitch, yaw, 0, 'YXZ');
