614:   stick.addEventListener('pointerdown', (event) => {
615:     event.preventDefault(); stick.setPointerCapture(event.pointerId);
616:     touch.stickId = event.pointerId;
617:     updateStick(event);
618:   });
619:   stick.addEventListener('pointermove', (event) => { if (touch.stickId === event.pointerId) updateStick(event); });
620:   const end = (event) => {
621:     if (touch.stickId !== event.pointerId) return;
