625:   function updateStick(event) {
626:     const rect = stick.getBoundingClientRect();
627:     let x = event.clientX - (rect.left + rect.width / 2);
628:     let y = event.clientY - (rect.top + rect.height / 2);
629:     const length = Math.hypot(x, y);
630:     if (length > radius) { x *= radius / length; y *= radius / length; }
631:     knob.style.transform = `translate(${x}px, ${y}px)`;
632:     touch.moveX = x / radius; touch.moveY = -y / radius;
633:   }
